package com.fatec.sgb

import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.view.ViewGroup
import android.widget.FrameLayout
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import androidx.viewpager2.adapter.FragmentStateAdapter
import com.fatec.sgb.adapters.AdapterEmprestimos
import com.fatec.sgb.adapters.AdapterLivros
import com.fatec.sgb.models.Emprestimo
import com.fatec.sgb.models.Livro
import com.fatec.sgb.retrofit.RetrofitClient
import com.google.android.material.tabs.TabLayoutMediator
import com.fatec.sgb.databinding.ActivityMainBinding
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding

    private lateinit var livrosFragment: LivrosFragment
    private lateinit var emprestimosFragment: EmprestimosFragment
    private var loadingRequests = 0

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        setSupportActionBar(binding.toolbar)

        livrosFragment = LivrosFragment()
        emprestimosFragment = EmprestimosFragment()

        val pagerAdapter = object : FragmentStateAdapter(this) {
            override fun getItemCount(): Int = 2
            override fun createFragment(position: Int): Fragment = when (position) {
                0 -> livrosFragment
                else -> emprestimosFragment
            }
        }

        binding.viewPager.adapter = pagerAdapter

        TabLayoutMediator(binding.tabs, binding.viewPager) { tab, position ->
            tab.text = when (position) {
                0 -> "LIVROS"
                else -> "EMPRÉSTIMOS"
            }
        }.attach()

        binding.fabRefresh.setOnClickListener {
            fetchAll()
        }

        // initial load
        fetchAll()
    }

    private fun fetchAll() {
        fetchLivros()
        fetchEmprestimos()
    }

    private fun setLoading(active: Boolean) {
        loadingRequests = if (active) loadingRequests + 1 else (loadingRequests - 1).coerceAtLeast(0)
        binding.progressBar.visibility = if (loadingRequests > 0) View.VISIBLE else View.GONE
    }

    private fun fetchLivros() {
        setLoading(true)
        livrosFragment.showLoading(true)
        RetrofitClient.apiService.getLivros().enqueue(object : Callback<List<Livro>> {
            override fun onResponse(call: Call<List<Livro>>, response: Response<List<Livro>>) {
                setLoading(false)
                livrosFragment.showLoading(false)
                if (response.isSuccessful) {
                    val list = response.body() ?: emptyList()
                    livrosFragment.updateLivros(list)
                } else {
                    val msg = response.errorBody()?.string() ?: "Erro: ${response.code()}"
                    Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                }
            }

            override fun onFailure(call: Call<List<Livro>>, t: Throwable) {
                setLoading(false)
                livrosFragment.showLoading(false)
                Toast.makeText(this@MainActivity, "Falha: ${t.message}", Toast.LENGTH_LONG).show()
            }
        })
    }

    private fun fetchEmprestimos() {
        setLoading(true)
        emprestimosFragment.showLoading(true)
        RetrofitClient.apiService.getEmprestimos().enqueue(object : Callback<List<Emprestimo>> {
            override fun onResponse(call: Call<List<Emprestimo>>, response: Response<List<Emprestimo>>) {
                setLoading(false)
                emprestimosFragment.showLoading(false)
                if (response.isSuccessful) {
                    val list = response.body() ?: emptyList()
                    emprestimosFragment.updateEmprestimos(list)
                } else {
                    val msg = response.errorBody()?.string() ?: "Erro: ${response.code()}"
                    Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                }
            }

            override fun onFailure(call: Call<List<Emprestimo>>, t: Throwable) {
                setLoading(false)
                emprestimosFragment.showLoading(false)
                Toast.makeText(this@MainActivity, "Falha: ${t.message}", Toast.LENGTH_LONG).show()
            }
        })
    }

    // Fragment to display livros
    class LivrosFragment : Fragment() {
        private var recyclerView: RecyclerView? = null
        private var emptyView: TextView? = null
        private var livros: List<Livro> = emptyList()

        override fun onCreateView(inflater: android.view.LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
            val root = FrameLayout(requireContext())
            root.layoutParams = ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)

            val rv = RecyclerView(requireContext())
            rv.layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
            rv.layoutManager = LinearLayoutManager(requireContext())
            recyclerView = rv

            val ev = TextView(requireContext()).apply {
                layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    gravity = Gravity.CENTER
                }
                text = getString(R.string.empty_livros)
                visibility = View.GONE
            }
            emptyView = ev

            root.addView(rv)
            root.addView(ev)
            render()

            return root
        }

        @Suppress("UNUSED_PARAMETER")
        fun showLoading(show: Boolean) { }

        fun updateLivros(list: List<Livro>) {
            livros = list
            render()
        }

        private fun render() {
            val rv = recyclerView ?: return
            val ev = emptyView ?: return
            if (livros.isEmpty()) {
                ev.visibility = View.VISIBLE
                rv.adapter = null
            } else {
                ev.visibility = View.GONE
                rv.adapter = AdapterLivros(livros)
            }
        }
    }

    // Fragment to display emprestimos
    class EmprestimosFragment : Fragment() {
        private var recyclerView: RecyclerView? = null
        private var emptyView: TextView? = null
        private var emprestimos: List<Emprestimo> = emptyList()

        override fun onCreateView(inflater: android.view.LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
            val root = FrameLayout(requireContext())
            root.layoutParams = ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)

            val rv = RecyclerView(requireContext())
            rv.layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
            rv.layoutManager = LinearLayoutManager(requireContext())
            recyclerView = rv

            val ev = TextView(requireContext()).apply {
                layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    gravity = Gravity.CENTER
                }
                text = getString(R.string.empty_emprestimos)
                visibility = View.GONE
            }
            emptyView = ev

            root.addView(rv)
            root.addView(ev)
            render()

            return root
        }

        @Suppress("UNUSED_PARAMETER")
        fun showLoading(show: Boolean) { }

        fun updateEmprestimos(list: List<Emprestimo>) {
            emprestimos = list
            render()
        }

        private fun render() {
            val rv = recyclerView ?: return
            val ev = emptyView ?: return
            if (emprestimos.isEmpty()) {
                ev.visibility = View.VISIBLE
                rv.adapter = null
            } else {
                ev.visibility = View.GONE
                rv.adapter = AdapterEmprestimos(emprestimos)
            }
        }
    }
}

package com.fatec.sgb.adapters

import android.graphics.Color
import android.graphics.Typeface
import android.view.Gravity
import android.view.Menu
import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView
import com.fatec.sgb.models.Emprestimo
import java.time.OffsetDateTime
import java.time.format.DateTimeFormatter

class AdapterEmprestimos(private val emprestimos: List<Emprestimo>) : RecyclerView.Adapter<AdapterEmprestimos.ViewHolder>() {

    var posicaoClicada: Int = -1
    var onItemClick: ((Emprestimo) -> Unit)? = null

    companion object {
        private const val MENU_REGISTRAR_DEVOLUCAO = 2001
    }

    inner class ViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView), View.OnCreateContextMenuListener {
        val tvUsuario: TextView
        val tvTituloLivro: TextView
        val tvStatus: TextView
        val tvMulta: TextView
        val tvDataPrevista: TextView

        init {
            val root = itemView as ViewGroup
            tvUsuario = root.findViewWithTag("tvUsuario") as TextView
            tvTituloLivro = root.findViewWithTag("tvTituloLivro") as TextView
            tvStatus = root.findViewWithTag("tvStatus") as TextView
            tvMulta = root.findViewWithTag("tvMulta") as TextView
            tvDataPrevista = root.findViewWithTag("tvDataPrevista") as TextView

            itemView.setOnCreateContextMenuListener(this)

            itemView.setOnLongClickListener {
                posicaoClicada = bindingAdapterPosition
                // return false to allow context menu to show
                false
            }

            itemView.setOnClickListener {
                val pos = bindingAdapterPosition
                if (pos != RecyclerView.NO_POSITION) onItemClick?.invoke(emprestimos[pos])
            }
        }

        override fun onCreateContextMenu(menu: android.view.ContextMenu, v: View, menuInfo: android.view.ContextMenu.ContextMenuInfo?) {
            menu.setHeaderTitle("Opções")
            menu.add(Menu.NONE, MENU_REGISTRAR_DEVOLUCAO, Menu.NONE, "Registrar Devolução")
        }
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val context = parent.context

        val card = CardView(context).apply {
            layoutParams = RecyclerView.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            radius = 8f
            cardElevation = 6f
            setContentPadding(20, 20, 20, 20)
        }

        val column = LinearLayout(context).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        val tvUsuario = TextView(context).apply {
            textSize = 16f
            setTypeface(null, Typeface.BOLD)
            tag = "tvUsuario"
            setTextColor(Color.BLACK)
        }

        val tvTituloLivro = TextView(context).apply {
            textSize = 14f
            tag = "tvTituloLivro"
            setTextColor(Color.DKGRAY)
        }

        val tvStatus = TextView(context).apply {
            textSize = 14f
            tag = "tvStatus"
        }

        val tvMulta = TextView(context).apply {
            textSize = 14f
            tag = "tvMulta"
            visibility = View.GONE
        }

        val tvDataPrevista = TextView(context).apply {
            textSize = 12f
            tag = "tvDataPrevista"
            setTextColor(Color.DKGRAY)
        }

        column.addView(tvUsuario)
        column.addView(tvTituloLivro)
        column.addView(tvStatus)
        column.addView(tvMulta)
        column.addView(tvDataPrevista)

        card.addView(column)

        return ViewHolder(card)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        val emprestimo = emprestimos[position]
        holder.tvUsuario.text = emprestimo.usuario.nome
        holder.tvTituloLivro.text = emprestimo.livro.titulo

        // Status color: green Finalizado, yellow Ativo, red Atrasado
        val status = emprestimo.status ?: ""
        val color = when (status.lowercase()) {
            "finalizado" -> Color.parseColor("#2E7D32")
            "ativo" -> Color.parseColor("#FBC02D")
            "atrasado" -> Color.parseColor("#C62828")
            else -> Color.BLACK
        }
        holder.tvStatus.text = status
        holder.tvStatus.setTextColor(color)

        // Multa
        if (emprestimo.valorMulta > 0.0) {
            holder.tvMulta.visibility = View.VISIBLE
            holder.tvMulta.text = String.format("Multa: R$ %.2f", emprestimo.valorMulta)
            holder.tvMulta.setTextColor(Color.parseColor("#C62828"))
        } else {
            holder.tvMulta.visibility = View.GONE
        }

        // Data prevista formatada
        holder.tvDataPrevista.text = try {
            val odt = OffsetDateTime.parse(emprestimo.dataPrevistaDevolucao)
            val fmt = DateTimeFormatter.ofPattern("dd/MM/yyyy")
            "Prevista: ${odt.format(fmt)}"
        } catch (e: Exception) {
            "Prevista: ${emprestimo.dataPrevistaDevolucao}"
        }
    }

    override fun getItemCount(): Int = emprestimos.size
}

