            "Prevista: ${odt.format(fmt)}"
        } catch (_: Exception) {
            "Prevista: ${emprestimo.dataPrevistaDevolucao}"
        }
    }

    override fun getItemCount(): Int = emprestimos.size
}

package com.fatec.sgb.retrofit

import com.fatec.sgb.models.Emprestimo
import com.fatec.sgb.models.Livro
import com.fatec.sgb.models.MensagemResposta
import com.fatec.sgb.models.Unidade
import com.fatec.sgb.models.Usuario
import retrofit2.Call
import retrofit2.http.Body
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.POST
import retrofit2.http.PUT
import retrofit2.http.Query

interface ApiService {
    @GET("api/livros")
    fun getLivros(): Call<List<Livro>>

    @GET("api/livros/disponiveis")
    fun getLivrosDisponiveis(): Call<List<Livro>>

    @GET("api/livros/buscar")
    fun buscarLivros(@Query("q") termo: String): Call<List<Livro>>

    @GET("api/livros/{id}")
    fun getLivroPorId(@Path("id") id: String): Call<Livro>

    @GET("api/emprestimos")
    fun getEmprestimos(): Call<List<Emprestimo>>

    @GET("api/emprestimos/atrasados")
    fun getEmprestimosAtrasados(): Call<List<Emprestimo>>

    @POST("api/emprestimos")
    fun realizarEmprestimo(@Body emprestimo: Emprestimo): Call<Emprestimo>

    @PUT("api/emprestimos/{id}/devolver")
    fun registrarDevolucao(@Path("id") id: String): Call<MensagemResposta>

    @GET("api/usuarios")
    fun getUsuarios(): Call<List<Usuario>>

    @GET("api/unidades")
    fun getUnidades(): Call<List<Unidade>>
}

package com.fatec.sgb.retrofit
import okhttp3.Interceptor import okhttp3.OkHttpClient import okhttp3.logging.HttpLoggingInterceptor import retrofit2.Retrofit import retrofit2.converter.gson.GsonConverterFactory import java.util.concurrent.TimeUnit
object RetrofitClient {
private const val BASE_URL = "https://sgb-api-bj4b.onrender.com/" private const val API_KEY = "chave_super_secreta_32_bytes"
private val apiKeyInterceptor = Interceptor { chain -> val original = chain.request() val request = original.newBuilder() .header("x-api-key", API_KEY) .method(original.method, original.body) .build() chain.proceed(request) }
private val logging = HttpLoggingInterceptor().apply { level = HttpLoggingInterceptor.Level.BASIC }
private val okHttpClient: OkHttpClient = OkHttpClient.Builder() .addInterceptor(apiKeyInterceptor) .addInterceptor(logging) .connectTimeout(30, TimeUnit.SECONDS) .readTimeout(30, TimeUnit.SECONDS) .build()
private val retrofit: Retrofit = Retrofit.Builder() .baseUrl(BASE_URL) .client(okHttpClient) .addConverterFactory(GsonConverterFactory.create()) .build()
val apiService: ApiService = retrofit.create(ApiService::class.java) }

package ronny.sousa.appcontatosrecycle

import android.content.Intent
import android.net.Uri
import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import android.view.MenuItem
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import ronny.sousa.appcontatosrecycle.adapters.AdapterContatos
import ronny.sousa.appcontatosrecycle.models.Contato

class MainActivity : AppCompatActivity() {
    val listaContatos = ArrayList<Contato>()
    lateinit var recycleContatos:RecyclerView
    lateinit var adapter:AdapterContatos

    init {


    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        recycleContatos = findViewById(R.id.listaContatos)
        adapter = AdapterContatos(listaContatos)
        recycleContatos.adapter = adapter
        recycleContatos.layoutManager=LinearLayoutManager(this)

    }

    override fun onResume() {
        super.onResume()
    }

    override fun onContextItemSelected(item: MenuItem): Boolean {

        val contato = listaContatos[ adapter.posicaoClicada]
        if (item.itemId == R.id.mapa_contato)
        {
            val uri=Uri.parse("geo:0,0?q=" +
                    contato.endereco +"&z=19")
            val intent = Intent(Intent.ACTION_VIEW,uri)
            startActivity(intent)
        }
        else if (item.itemId == R.id.email_contato)
        {
            val uri=Uri.parse("mailto:" +
                    contato.email)
            val intent = Intent(Intent.ACTION_VIEW,uri)
            startActivity(intent)
        }
        else if (item.itemId == R.id.ligacao_contato)
        {
            val uri=Uri.parse("tel:" +
                    contato.telefone)
            val intent = Intent(Intent.ACTION_VIEW,uri)
            startActivity(intent)
        }
        return true

    }
}

