package com.fatec.sgb.retrofit
import okhttp3.Interceptor import okhttp3.OkHttpClient import okhttp3.logging.HttpLoggingInterceptor import retrofit2.Retrofit import retrofit2.converter.gson.GsonConverterFactory
object RetrofitClient { const val BASE_URL = "https://sgb-api-bj4b.onrender.com/" const val API_KEY = "chave_super_secreta_32_bytes"
private val apiKeyInterceptor = Interceptor { chain -> val request = chain.request().newBuilder() .addHeader("x-api-key", API_KEY) .build() chain.proceed(request) }
private val loggingInterceptor = HttpLoggingInterceptor().apply { level = HttpLoggingInterceptor.Level.BODY }
private val okHttpClient: OkHttpClient = OkHttpClient.Builder() .addInterceptor(apiKeyInterceptor) .addInterceptor(loggingInterceptor) .build()
val retrofit: Retrofit = Retrofit.Builder() .baseUrl(BASE_URL) .client(okHttpClient) .addConverterFactory(GsonConverterFactory.create()) .build()
val apiService: ApiService = retrofit.create(ApiService::class.java) }

